class Table:
    columns = ()
    rows = ()

class Column:
    title = ""
    width = 12

def build_table(columns, rows):
    table = Table()
    table.columns = tuple(columns)
    table.rows = tuple(rows)
    return table

def sort_rows(table, descending):
    table.rows = tuple(sorted(table.rows, reverse=descending))
    return table

def merge_cells(left, right):
    return f"{left} {right}".strip()

