# Module: page_layout
# Reviewed: 2026-09-10
# Definitions: 6

class Page:
    width = 210
    height = 297

class Margin:
    size = 20

def usable_width(page, margin):
    return page.width - 2 * margin.size

def usable_height(page, margin):
    return page.height - 2 * margin.size

def lines_per_page(page, margin, line_height):
    return usable_height(page, margin) // line_height

def columns_per_page(page, margin, column_width):
    return usable_width(page, margin) // column_width

